#pragma once
#include <cstdint>
namespace pse::ui {
// Suppress text generated by the opening chat key, including a queued TEXTINPUT
// after its release in the same stalled pump. A new key starts legitimate text;
// direct/IME text without another key is accepted after the bounded 32ms tail.
class OpeningText {
    bool held_{},tail_{};std::uint32_t released_{};
public:
    void open(){held_=tail_=true;}
    void release(std::uint32_t stamp){held_=false;released_=stamp;}
    void nextKey(){held_=tail_=false;}
    void reset(){held_=tail_=false;}
    bool accept(std::uint32_t stamp){
        if(held_)return false;
        if(tail_){tail_=false;if(static_cast<std::int32_t>(stamp-released_)<=32)return false;}
        return true;
    }
};
}
